// Demonstration documents shipped in `public/intellieditor/` (generated by
// `packages/conformity/scripts/make-samples.ts`). Same-origin, fetched on a user action only.

import type { CoverLogo } from '@intellieditor/conformity';

export const SAMPLES = {
  compliant: { file: 'tfc-exemple-conforme.docx', label: 'Exemple : TFC complet conforme' },
  flawed: { file: 'tfc-exemple-erreurs.docx', label: 'Exemple : TFC avec erreurs' },
  model: { file: 'tfc-modele-udbl.docx', label: 'Exemple : modèle UDBL conforme' },
} as const;

export type SampleId = keyof typeof SAMPLES;

export async function fetchSample(id: SampleId): Promise<Uint8Array> {
  const response = await fetch(`${import.meta.env.BASE_URL}intellieditor/${SAMPLES[id].file}`);
  if (!response.ok) throw new Error(`exemple introuvable (${response.status})`);
  return new Uint8Array(await response.arrayBuffer());
}

/** The UDBL logo « Nouveau TFC » puts on the cover by default. */
export async function fetchDefaultLogo(): Promise<CoverLogo | null> {
  try {
    const response = await fetch(`${import.meta.env.BASE_URL}intellieditor/logo-udbl.png`);
    if (!response.ok) return null;
    return { bytes: new Uint8Array(await response.arrayBuffer()), format: 'png' };
  } catch {
    return null;
  }
}
